                    @forelse($parsedLines as $i=>$line)
                        @php $rowCost=(float)str_replace(['$',','],'',(string)($line['unit_cost']??0)); $rowTotal=max(0,(int)($line['case_count']??0))*max(1,(float)($line['quantity_per_case']??1))*$rowCost; $isMatched=!empty($line['matched_item_id']) && empty($line['create_new_item']); $conf=(float)($line['match_confidence_score']??0); $confLabel=$conf >= .95 ? 'High' : ($conf >= .75 ? 'Medium' : 'Low'); @endphp
                        <div class="vx-item-wrap" wire:key="manifest-line-{{ $i }}"><div class="vx-item-row"><div class="vx-item-index">{{ $i+1 }}</div><div class="vx-item-main"><div class="vx-thumb">{{ strtoupper(substr(trim($line['description'] ?? 'I'),0,1)) }}</div><div class="vx-item-copy"><div class="vx-item-name">{{ $line['description'] ?: 'Untitled manifest item' }}</div><div class="vx-item-sub">{{ $isMatched ? 'From: '.($line['matched_item_name'] ?? 'Inventory match') : 'From: Supplier Invoice' }}</div></div></div><div><input class="vx-input" type="number" min="1" wire:model="parsedLines.{{ $i }}.case_count" /></div><div><input class="vx-input" type="number" min="1" wire:model="parsedLines.{{ $i }}.quantity_per_case" /></div><div><div class="vx-money"><span>$</span><input class="vx-input" wire:model="parsedLines.{{ $i }}.unit_cost" /></div></div><div class="vx-total-cell">${{ number_format($rowTotal,2) }}</div><div class="vx-match">@if($isMatched)<span class="vx-status-pill">✓ Matched</span><div class="vx-match-meta">Confidence: {{ $confLabel }}</div>@elseif(!empty($line['create_new_item']))<span class="vx-status-pill new">＋ Create New</span><div class="vx-match-meta">Suggested new inventory item</div>@else<span class="vx-status-pill review">Review</span><div class="vx-match-meta">Needs inventory decision</div>@endif</div><div class="vx-row-actions"><details class="vx-details"><summary class="vx-icon-btn" title="Edit item">✎</summary><div class="vx-edit-panel"><div class="vx-edit-grid"><div class="full"><label class="vx-label">Item Description</label><input class="vx-input" wire:model="parsedLines.{{ $i }}.description" /></div><div><label class="vx-label">SKU</label><input class="vx-input" wire:model="parsedLines.{{ $i }}.sku" /></div><div><label class="vx-label">Barcode</label><input class="vx-input" wire:model="parsedLines.{{ $i }}.barcode" /></div></div></div></details><details class="vx-menu"><summary class="vx-icon-btn" title="Match options">⋮</summary><div class="vx-menu-panel"><div class="vx-menu-title">Inventory Match</div><div class="vx-match-options">@if($isMatched)<button type="button" class="vx-match-option" disabled>✓ Current: {{ $line['matched_item_name'] }}</button>@endif @if(!empty($line['alternatives'])) @foreach(array_slice($line['alternatives'],0,4) as $alt)<button type="button" class="vx-match-option" wire:click="chooseMatch({{ $i }}, {{ $alt['id'] }})">{{ $alt['name'] }}</button>@endforeach @endif <button type="button" class="vx-match-option create" wire:click="chooseCreateNew({{ $i }})">＋ Create New Inventory Item</button></div></div></details><button type="button" class="vx-remove-btn" wire:click="removeLine({{ $i }})">Remove Line</button></div></div></div>
                    @empty<div class="p-8 text-center text-xs text-gray-500">No extracted lines were returned.</div>@endforelse
                    <div class="vx-items-foot"><button type="button" wire:click="addLine" class="vx-btn">＋ Add Manual Item</button><div class="vx-totals"><div class="vx-total"><span>Total Cases</span><strong>{{ number_format($totalCases) }}</strong></div><div class="vx-total"><span>Total Units</span><strong>{{ number_format($totalUnits) }}</strong></div><div class="vx-total"><span>Estimated Value</span><strong>${{ number_format($estimatedValue,2) }}</strong></div></div></div>
                </section>
                <div class="vx-footer"><div class="vx-footer-note">{{ $reviewCount }} item{{ $reviewCount===1?'':'s' }} still need review. Approving saves the manifest; physical receiving remains separate.</div><div class="vx-actions"><button wire:click="startOver" class="vx-btn">Start Over</button><button wire:click="import" wire:loading.attr="disabled" class="vx-btn primary"><span wire:loading.remove wire:target="import">Add Items to Pallet →</span><span wire:loading wire:target="import">Adding…</span></button></div></div>
            </section>
        </div>
    @endif

    @if($stage === 'done')<section class="vx-card vx-section text-center"><x-heroicon-o-check-circle class="mx-auto h-10 w-10 text-emerald-500" /><h2 class="mt-2 text-lg font-bold">Manifest approved</h2><p class="mt-1 text-xs text-gray-500">{{ $created }} lines processed · {{ $matched }} matched · {{ $unmatched }} unmatched.</p><a href="{{ $palletUrl }}" class="vx-btn primary mt-4">Return to Pallet</a></section>@endif
</div>
</x-filament-panels::page>